'AC-reconciliation.review-queue.1'; from dataclasses import replace; from datetime import date; from decimal import Decimal; import pytest; from src.reconciliation.base.config import DEFAULT_CONFIG; from src.reconciliation.base.scoring_engine import derive_reconciliation_score_tier, extract_merchant_tokens, is_cross_period, normalize_text, score_amount, score_date, score_description; pytestmark = pytest.mark.no_db
def test_score_amount_exact_and_tolerances(): 'AC-reconciliation.review-queue.1'; config = replace(DEFAULT_CONFIG, amount_percent=Decimal('0.02'), amount_absolute=Decimal('1.00')); assert score_amount(Decimal('100.00'), Decimal('100.00'), config) == 100.0; assert score_amount(Decimal('100.00'), Decimal('100.01'), config) == 100.0; assert score_amount(Decimal('100.00'), Decimal('101.50'), config) == 90.0; assert score_amount(Decimal('100.00'), Decimal('104.00'), config) == 70.0; assert score_amount(Decimal('100.00'), Decimal('200.00'), config) == 0.0; 'AC-reconciliation.review-queue.1'; 'AC-reconciliation.review-queue.1'; _m1_config = replace(DEFAULT_CONFIG, date_days=7); _m1_d1 = date(2025, 4, 15); assert score_date(_m1_d1, _m1_d1, _m1_config) == 100.0; assert score_date(_m1_d1, date(2025, 4, 17), _m1_config) == 90.0; assert score_date(_m1_d1, date(2025, 4, 21), _m1_config) == 70.0; _m1_apr_27 = date(2025, 4, 27); _m1_may_02 = date(2025, 5, 2); assert is_cross_period(_m1_apr_27, _m1_may_02, max_days=7) is True; assert score_date(_m1_apr_27, _m1_may_02, _m1_config) == 75.0; 'AC-reconciliation.review-queue.1'; 'AC-reconciliation.review-queue.1'; assert normalize_text('  GRAB* TAXI / TRIP #123  ') == 'grab taxi trip 123'; _m2_tokens = extract_merchant_tokens('POS DEBIT 987654 NETFLIX COM SINGAPORE'); assert 'netflix' in _m2_tokens; assert 'singapore' in _m2_tokens; assert 'pos' not in _m2_tokens; assert 'debit' not in _m2_tokens; 'AC-reconciliation.review-queue.1'; 'AC-reconciliation.review-queue.1'; assert derive_reconciliation_score_tier(None) == 'LOW'; assert derive_reconciliation_score_tier(59) == 'LOW'; assert derive_reconciliation_score_tier(60) == 'MEDIUM'; assert derive_reconciliation_score_tier(84) == 'MEDIUM'; assert derive_reconciliation_score_tier(85) == 'HIGH'; assert derive_reconciliation_score_tier(100) == 'HIGH'; 'AC-reconciliation.review-queue.1'; 'AC-reconciliation.review-queue.1'; assert score_description(None, 'Grab Taxi') == 0.0; assert score_description('Grab Taxi', None) == 0.0; assert score_description('Grab Taxi Singapore', 'Grab Taxi Singapore') == 100.0; assert score_description('Grab Taxi', 'Grab Car') > 40.0
